import sys

class Student:
    def __init__(self):
        self.name = ""
        self.marks = 0

    def input(self):
        parts = sys.stdin.readline().split()
        if len(parts) >= 2:
            self.name = parts[0]
            self.marks = int(parts[1])

    def display(self):
        print(f"Name: {self.name}, Marks: {self.marks}")

    @staticmethod
    def calculateAverage(students):
        n = len(students)
        if n == 0:
            return 0.0
        total = sum(s.marks for s in students)
        return total / n


def main():
    line = sys.stdin.readline()
    if not line:
        return
    n = int(line.strip())

    students = []
    for _ in range(n):
        s = Student()
        s.input()
        students.append(s)

    print("Student Details:")
    for s in students:
        s.display()

    avg = Student.calculateAverage(students)
    print(f"Average Marks: {int(avg)}")


if __name__ == "__main__":
    main()
